setup.test_csvstats.py:
from csvstats import column_means, parse_rows

CSV = "name,age,score\nalice,30,90\nbob,25,80\n"


def test_parse_rows_drops_the_header_and_splits_cells():
    assert parse_rows(CSV) == [["alice", "30", "90"], ["bob", "25", "80"]]


def test_column_means_averages_numeric_columns():
    assert column_means(CSV, ["age", "score"]) == {"age": 27.5, "score": 85.0}


def test_column_means_skips_columns_without_numbers():
    assert column_means(CSV, ["name"]) == {}


def test_column_means_is_empty_without_data_rows():
    assert column_means("a,b\n", ["a"]) == {}
